/* pg8.c -- independent PG(2,8) / PGL(3,8) engine for the K1327 all-orbits check.
 *
 * Everything is rebuilt from scratch:
 *   - GF(8) = GF(2)[x]/(x^3+x+1), element a0+a1 x+a2 x^2 <-> int a0+2a1+4a2
 *   - points = 1-dim subspaces of GF(8)^3, canonical rep (first nonzero coord 1),
 *     board index = rank among canonical vectors sorted by integer value
 *   - lines = spans of point pairs
 *   - PGL(3,8) generated by four explicit matrices D,T,S,U
 *
 * Usage (argv[1]):
 *   verify    <board>   board syntax + line-set check, generator collineation check
 *   order               |<D,T,S,U>| via BFS on ordered 4-arcs (free action)
 *   census              enumerate all caps by size
 *   decompose           orbit decomposition of the caps of every size
 *   orbits              orbit sizes of the K1327 start caps and the conic layers
 *   all       <board>   verify + order + census + decompose + orbits
 *
 * Output lines are "key=value" so a Python driver can parse them.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* ------------------------------------------------------------------ GF(8) */
static int GF_EXP[7];
static int GF_LOG[8];

static void gf_init(void) {
    int x = 1;
    for (int i = 0; i < 7; i++) {
        GF_EXP[i] = x;
        GF_LOG[x] = i;
        x <<= 1;
        if (x & 8) x ^= 0xB; /* x^3 = x + 1 */
    }
    GF_LOG[0] = 0;
}
static inline int gf_mul(int a, int b) {
    if (!a || !b) return 0;
    return GF_EXP[(GF_LOG[a] + GF_LOG[b]) % 7];
}
static inline int gf_inv(int a) { return GF_EXP[(7 - GF_LOG[a]) % 7]; }

/* --------------------------------------------------------------- vectors */
typedef struct { int v[3]; } Vec;

static Vec vnorm(Vec a) {
    for (int i = 0; i < 3; i++) {
        if (a.v[i]) {
            int inv = gf_inv(a.v[i]);
            Vec r;
            for (int j = 0; j < 3; j++) r.v[j] = gf_mul(inv, a.v[j]);
            return r;
        }
    }
    Vec z = {{0, 0, 0}};
    return z;
}

static Vec PT[73];
static int PIX[8][8][8];

static void points_init(void) {
    int keys[512];
    Vec tmp[512];
    int nk = 0;
    for (int a = 0; a < 8; a++)
        for (int b = 0; b < 8; b++)
            for (int c = 0; c < 8; c++) {
                if (!a && !b && !c) continue;
                Vec v = {{a, b, c}};
                Vec w = vnorm(v);
                int dup = 0;
                for (int t = 0; t < nk; t++)
                    if (tmp[t].v[0] == w.v[0] && tmp[t].v[1] == w.v[1] && tmp[t].v[2] == w.v[2]) { dup = 1; break; }
                if (!dup) {
                    keys[nk] = (w.v[0] << 6) | (w.v[1] << 3) | w.v[2];
                    tmp[nk] = w;
                    nk++;
                }
            }
    if (nk != 73) { fprintf(stderr, "FATAL: %d canonical points\n", nk); exit(1); }
    for (int i = 1; i < nk; i++) { /* insertion sort by numeric key */
        int k = keys[i];
        Vec v = tmp[i];
        int j = i - 1;
        while (j >= 0 && keys[j] > k) { keys[j + 1] = keys[j]; tmp[j + 1] = tmp[j]; j--; }
        keys[j + 1] = k;
        tmp[j + 1] = v;
    }
    for (int a = 0; a < 8; a++)
        for (int b = 0; b < 8; b++)
            for (int c = 0; c < 8; c++) PIX[a][b][c] = -1;
    for (int i = 0; i < 73; i++) {
        PT[i] = tmp[i];
        PIX[tmp[i].v[0]][tmp[i].v[1]][tmp[i].v[2]] = i;
    }
}

static int vdot(Vec a, Vec b) {
    return gf_mul(a.v[0], b.v[0]) ^ gf_mul(a.v[1], b.v[1]) ^ gf_mul(a.v[2], b.v[2]);
}
static Vec vcross(Vec a, Vec b) {
    Vec r;
    r.v[0] = gf_mul(a.v[1], b.v[2]) ^ gf_mul(a.v[2], b.v[1]);
    r.v[1] = gf_mul(a.v[2], b.v[0]) ^ gf_mul(a.v[0], b.v[2]);
    r.v[2] = gf_mul(a.v[0], b.v[1]) ^ gf_mul(a.v[1], b.v[0]);
    return r;
}
static Vec matvec(int M[3][3], Vec v) {
    Vec r;
    for (int i = 0; i < 3; i++)
        r.v[i] = gf_mul(M[i][0], v.v[0]) ^ gf_mul(M[i][1], v.v[1]) ^ gf_mul(M[i][2], v.v[2]);
    return r;
}
static int matdet(int M[3][3]) {
    return gf_mul(M[0][0], gf_mul(M[1][1], M[2][2]) ^ gf_mul(M[1][2], M[2][1]))
         ^ gf_mul(M[0][1], gf_mul(M[1][0], M[2][2]) ^ gf_mul(M[1][2], M[2][0]))
         ^ gf_mul(M[0][2], gf_mul(M[1][0], M[2][1]) ^ gf_mul(M[1][1], M[2][0]));
}

/* ------------------------------------------------------------------ masks */
typedef struct { uint64_t lo, hi; } Mask; /* lo = points 0..63, hi = 64..72 */

static inline Mask FULL73(void) { Mask m = {~0ULL, 0x1FFULL}; return m; }
static inline int mget(Mask m, int i) {
    return i < 64 ? (int)((m.lo >> i) & 1) : (int)((m.hi >> (i - 64)) & 1);
}
static inline Mask mset(Mask m, int i) {
    if (i < 64) m.lo |= 1ULL << i; else m.hi |= 1ULL << (i - 64);
    return m;
}
static inline Mask mor(Mask a, Mask b) { Mask r = {a.lo | b.lo, a.hi | b.hi}; return r; }
static inline Mask mand(Mask a, Mask b) { Mask r = {a.lo & b.lo, a.hi & b.hi}; return r; }
static inline Mask mnot(Mask a) { Mask r = {~a.lo, ~a.hi}; return r; }
static inline int meq(Mask a, Mask b) { return a.lo == b.lo && a.hi == b.hi; }
static inline int mzero(Mask a) { return a.lo == 0 && a.hi == 0; }
static inline int mpop(Mask a) { return __builtin_popcountll(a.lo) + __builtin_popcountll(a.hi); }

static inline Mask mact(const int *perm, Mask m) {
    Mask r = {0, 0};
    uint64_t x = m.lo;
    while (x) {
        int b = __builtin_ctzll(x);
        x &= x - 1;
        int q = perm[b];
        if (q < 64) r.lo |= 1ULL << q; else r.hi |= 1ULL << (q - 64);
    }
    x = m.hi;
    while (x) {
        int b = __builtin_ctzll(x);
        x &= x - 1;
        int q = perm[64 + b];
        if (q < 64) r.lo |= 1ULL << q; else r.hi |= 1ULL << (q - 64);
    }
    return r;
}

static uint64_t mhash(Mask m) {
    uint64_t x = m.lo ^ (m.hi * 0x9E3779B97F4A7C15ULL);
    x ^= x >> 33;
    x *= 0xFF51AFD7ED558CCDULL;
    x ^= x >> 33;
    x *= 0xC4CEB9FE1A85EC53ULL;
    x ^= x >> 33;
    return x;
}

/* ------------------------------------------------------------- hash table */
/* Key (0,0) marks an empty slot; every real key is a non-empty point set. */
typedef struct {
    Mask *keys;
    int32_t *vals;
    size_t cap, mask, used;
} Map;

static void map_init(Map *m, size_t mincap) {
    size_t cap = 16;
    while (cap < mincap * 2) cap <<= 1;
    m->keys = (Mask *)calloc(cap, sizeof(Mask));
    m->vals = (int32_t *)malloc(cap * sizeof(int32_t));
    if (!m->keys || !m->vals) { fprintf(stderr, "OOM map cap=%zu\n", cap); exit(1); }
    m->cap = cap;
    m->mask = cap - 1;
    m->used = 0;
    for (size_t i = 0; i < cap; i++) m->vals[i] = -1;
}

static void map_free(Map *m) { free(m->keys); free(m->vals); m->keys = NULL; m->vals = NULL; }

static void map_insert_raw(Map *m, Mask key, int32_t val) {
    size_t h = (size_t)mhash(key) & m->mask;
    while (!mzero(m->keys[h])) {
        if (meq(m->keys[h], key)) { m->vals[h] = val; return; }
        h = (h + 1) & m->mask;
    }
    m->keys[h] = key;
    m->vals[h] = val;
    m->used++;
}

static void map_grow(Map *m) {
    Map n;
    map_init(&n, m->cap); /* doubles capacity */
    for (size_t i = 0; i < m->cap; i++)
        if (!mzero(m->keys[i])) map_insert_raw(&n, m->keys[i], m->vals[i]);
    map_free(m);
    *m = n;
}

static void map_put(Map *m, Mask key, int32_t val) {
    if (m->used * 2 >= m->cap) map_grow(m);
    map_insert_raw(m, key, val);
}

static int32_t map_get(Map *m, Mask key) {
    size_t h = (size_t)mhash(key) & m->mask;
    while (!mzero(m->keys[h])) {
        if (meq(m->keys[h], key)) return m->vals[h];
        h = (h + 1) & m->mask;
    }
    return -1;
}

/* ------------------------------------------------------------ group data */
static int PERM[4][73];
static int NGEN = 4;
static Mask LINE[73];
static Mask PAIRLINE[73][73];
static int BOARD[73][9];
static int NBOARD = 0;

static int GENM[4][3][3] = {
    {{2, 0, 0}, {0, 1, 0}, {0, 0, 1}}, /* D : x0 -> x*x0         */
    {{1, 1, 0}, {0, 1, 0}, {0, 0, 1}}, /* T : x0 -> x0 + x1      */
    {{0, 1, 0}, {1, 0, 0}, {0, 0, 1}}, /* S : (x0,x1) -> (x1,x0) */
    {{1, 0, 0}, {0, 0, 1}, {0, 1, 0}}, /* U : (x1,x2) -> (x2,x1) */
};
static const char *GENNAME[4] = {"D", "T", "S", "U"};

static void group_init(void) {
    for (int g = 0; g < NGEN; g++) {
        if (matdet(GENM[g]) == 0) { fprintf(stderr, "FATAL singular generator\n"); exit(1); }
        for (int p = 0; p < 73; p++) {
            Vec im = vnorm(matvec(GENM[g], PT[p]));
            int q = PIX[im.v[0]][im.v[1]][im.v[2]];
            if (q < 0) { fprintf(stderr, "FATAL generator image not a point\n"); exit(1); }
            PERM[g][p] = q;
        }
    }
    int n = 0;
    for (int i = 0; i < 73; i++) {
        for (int j = i + 1; j < 73; j++) {
            Vec w = vcross(PT[i], PT[j]);
            Mask s = {0, 0};
            for (int k = 0; k < 73; k++)
                if (vdot(w, PT[k]) == 0) s = mset(s, k);
            if (mpop(s) != 9) { fprintf(stderr, "FATAL line size %d\n", mpop(s)); exit(1); }
            int found = -1;
            for (int t = 0; t < n; t++) if (meq(LINE[t], s)) { found = t; break; }
            if (found < 0) {
                if (n >= 73) { fprintf(stderr, "FATAL too many lines\n"); exit(1); }
                LINE[n++] = s;
            }
            PAIRLINE[i][j] = PAIRLINE[j][i] = s;
        }
    }
    if (n != 73) { fprintf(stderr, "FATAL %d lines\n", n); exit(1); }
}

/* ---------------------------------------------------------------- board */
static int load_board(const char *path) {
    FILE *f = fopen(path, "r");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); return 0; }
    int np, nl;
    if (fscanf(f, "%d %d", &np, &nl) != 2) { fclose(f); return 0; }
    if (np != 73 || nl != 73) { fclose(f); return 0; }
    NBOARD = nl;
    for (int i = 0; i < nl; i++) {
        int k;
        if (fscanf(f, "%d", &k) != 1 || k != 9) { fclose(f); return 0; }
        for (int j = 0; j < 9; j++)
            if (fscanf(f, "%d", &BOARD[i][j]) != 1) { fclose(f); return 0; }
    }
    fclose(f);
    return 1;
}

static int board_matches(void) {
    for (int i = 0; i < NBOARD; i++) {
        Mask s = {0, 0};
        for (int j = 0; j < 9; j++) s = mset(s, BOARD[i][j]);
        int hit = 0;
        for (int t = 0; t < 73; t++) if (meq(LINE[t], s)) { hit = 1; break; }
        if (!hit) return 0;
    }
    return 1;
}

/* ------------------------------------------------------- dynamic vectors */
typedef struct { Mask *items; size_t n, cap; } VecMask;
static void vm_init(VecMask *v, size_t cap) {
    v->items = (Mask *)malloc(cap * sizeof(Mask));
    if (!v->items) { fprintf(stderr, "OOM vm\n"); exit(1); }
    v->n = 0;
    v->cap = cap;
}
static void vm_push(VecMask *v, Mask m) {
    if (v->n == v->cap) {
        v->cap *= 2;
        v->items = (Mask *)realloc(v->items, v->cap * sizeof(Mask));
        if (!v->items) { fprintf(stderr, "OOM vm grow\n"); exit(1); }
    }
    v->items[v->n++] = m;
}

/* ---------------------------------------------- orbit BFS (hash visited) */
typedef struct {
    VecMask elems;
    Map seen;
} Orbit;

static void orbit_init(Orbit *o) {
    vm_init(&o->elems, 1024);
    map_init(&o->seen, 1024);
}

static long long orbit_run(Orbit *o, Mask start) {
    o->elems.n = 0;
    map_put(&o->seen, start, 0);
    vm_push(&o->elems, start);
    size_t head = 0;
    while (head < o->elems.n) {
        Mask cur = o->elems.items[head++];
        for (int g = 0; g < NGEN; g++) {
            Mask im = mact(PERM[g], cur);
            if (map_get(&o->seen, im) < 0) {
                map_put(&o->seen, im, 0);
                vm_push(&o->elems, im);
            }
        }
    }
    return (long long)o->elems.n;
}

/* Perturb the hash so a fresh BFS starts (only needed when reusing an Orbit) */
static void orbit_free(Orbit *o) {
    free(o->elems.items);
    map_free(&o->seen);
}

/* -------------------------------------- ordered 4-arc BFS -> |<generators>| */
static long long order_via_4arcs(int a, int b, int c, int d) {
    size_t nbytes = ((size_t)1 << 28) / 8; /* 4 x 7-bit point indices */
    uint8_t *vis = (uint8_t *)calloc(nbytes, 1);
    uint32_t *q = (uint32_t *)malloc(sizeof(uint32_t) * 17000000u);
    if (!vis || !q) { fprintf(stderr, "OOM 4arc\n"); exit(1); }
    uint32_t s0 = (uint32_t)a | ((uint32_t)b << 7) | ((uint32_t)c << 14) | ((uint32_t)d << 21);
    size_t head = 0, tail = 0;
    q[tail++] = s0;
    vis[s0 >> 3] |= (uint8_t)(1u << (s0 & 7));
    long long cnt = 0;
    while (head < tail) {
        uint32_t s = q[head++];
        cnt++;
        int p0 = s & 127, p1 = (s >> 7) & 127, p2 = (s >> 14) & 127, p3 = (s >> 21) & 127;
        for (int g = 0; g < NGEN; g++) {
            const int *pm = PERM[g];
            uint32_t t = (uint32_t)pm[p0] | ((uint32_t)pm[p1] << 7) |
                         ((uint32_t)pm[p2] << 14) | ((uint32_t)pm[p3] << 21);
            if (!(vis[t >> 3] & (1u << (t & 7)))) {
                vis[t >> 3] |= (uint8_t)(1u << (t & 7));
                q[tail++] = t;
            }
        }
    }
    free(vis);
    free(q);
    return cnt;
}

/* ------------------------------------------------------------------ caps */
static long long CNT[16];
static Mask *CAPS[16];
static size_t CAPN[16], CAPC[16];
static int STORE = 0;
static Mask *MAX6 = NULL;
static size_t MAX6N = 0, MAX6C = 0;

static void cap_store(int size, Mask cap, Mask forb) {
    CNT[size]++;
    if (size == 6 && meq(forb, FULL73())) {
        if (MAX6N == MAX6C) {
            MAX6C = MAX6C ? MAX6C * 2 : 1024;
            MAX6 = (Mask *)realloc(MAX6, MAX6C * sizeof(Mask));
            if (!MAX6) { fprintf(stderr, "OOM max6\n"); exit(1); }
        }
        MAX6[MAX6N++] = cap;
    }
    if (STORE) {
        if (CAPN[size] == CAPC[size]) {
            CAPC[size] = CAPC[size] ? CAPC[size] * 2 : 1024;
            CAPS[size] = (Mask *)realloc(CAPS[size], CAPC[size] * sizeof(Mask));
            if (!CAPS[size]) { fprintf(stderr, "OOM caps %d\n", size); exit(1); }
        }
        CAPS[size][CAPN[size]++] = cap;
    }
}

static void cap_dfs(Mask cap, Mask forb, int last, int size) {
    cap_store(size, cap, forb);
    Mask cand = mand(FULL73(), mnot(forb));
    for (int p = last + 1; p < 73; p++) {
        if (!mget(cand, p)) continue;
        Mask nf = mset(forb, p);
        Mask c = cap;
        while (c.lo) {
            int b = __builtin_ctzll(c.lo);
            c.lo &= c.lo - 1;
            nf = mor(nf, PAIRLINE[p][b]);
        }
        while (c.hi) {
            int b = __builtin_ctzll(c.hi);
            c.hi &= c.hi - 1;
            nf = mor(nf, PAIRLINE[p][64 + b]);
        }
        cap_dfs(mset(cap, p), nf, p, size + 1);
    }
}

static void census(int store) {
    STORE = store;
    memset(CNT, 0, sizeof CNT);
    MAX6N = 0;
    if (store) {
        for (int i = 0; i < 16; i++) { CAPN[i] = 0; CAPC[i] = 0; CAPS[i] = NULL; }
    }
    for (int p = 0; p < 73; p++) {
        Mask cap = {0, 0};
        cap = mset(cap, p);
        cap_dfs(cap, cap, p, 1);
    }
    STORE = 0;
}

/* ------------------------------------------------------------- utilities */
static Mask mask_of(const int *pts, int n) {
    Mask m = {0, 0};
    for (int i = 0; i < n; i++) m = mset(m, pts[i]);
    return m;
}
static void print_mask(Mask m) {
    int first = 1;
    for (int i = 0; i < 73; i++) if (mget(m, i)) {
        printf(first ? "%d" : ",%d", i);
        first = 0;
    }
}
static int is_cap(Mask m) {
    for (int i = 0; i < 73; i++) if (mget(m, i))
        for (int j = i + 1; j < 73; j++) if (mget(m, j)) {
            Mask inter = mand(PAIRLINE[i][j], m);
            if (mpop(inter) > 2) return 0;
        }
    return 1;
}
static int is_max_cap(Mask m) {
    Mask forb = m;
    for (int i = 0; i < 73; i++) if (mget(m, i))
        for (int j = i + 1; j < 73; j++) if (mget(m, j))
            forb = mor(forb, PAIRLINE[i][j]);
    return meq(forb, FULL73());
}

/* conic Q(x0,x1,x2) = x0^2 + x1*x2 (non-degenerate: 1 + x1 x2 = 0 has 7
 * affine solutions and 2 points at infinity) */
static Mask conic_mask(void) {
    Mask m = {0, 0};
    for (int i = 0; i < 73; i++) {
        Vec v = PT[i];
        if ((gf_mul(v.v[0], v.v[0]) ^ gf_mul(v.v[1], v.v[2])) == 0) m = mset(m, i);
    }
    return m;
}

/* Enumerate every quadratic form up to scalar and count the 9-point conics.
 * Q = a x0^2 + b x1^2 + c x2^2 + d x0x1 + e x0x2 + f x1x2                    */
static void enum_quads(void) {
    int coef[6];
    Map set;
    map_init(&set, 40000);
    long long nforms = 0, nconic = 0;
    for (int i0 = 0; i0 < 8; i0++)
    for (int i1 = 0; i1 < 8; i1++)
    for (int i2 = 0; i2 < 8; i2++)
    for (int i3 = 0; i3 < 8; i3++)
    for (int i4 = 0; i4 < 8; i4++)
    for (int i5 = 0; i5 < 8; i5++) {
        coef[0] = i0; coef[1] = i1; coef[2] = i2;
        coef[3] = i3; coef[4] = i4; coef[5] = i5;
        int first = -1;
        for (int i = 0; i < 6; i++) if (coef[i]) { first = i; break; }
        if (first < 0 || coef[first] != 1) continue; /* one rep per scalar class */
        nforms++;
        Mask m = {0, 0};
        for (int i = 0; i < 73; i++) {
            Vec v = PT[i];
            int q = gf_mul(coef[0], gf_mul(v.v[0], v.v[0]))
                  ^ gf_mul(coef[1], gf_mul(v.v[1], v.v[1]))
                  ^ gf_mul(coef[2], gf_mul(v.v[2], v.v[2]))
                  ^ gf_mul(coef[3], gf_mul(v.v[0], v.v[1]))
                  ^ gf_mul(coef[4], gf_mul(v.v[0], v.v[2]))
                  ^ gf_mul(coef[5], gf_mul(v.v[1], v.v[2]));
            if (q == 0) m = mset(m, i);
        }
        if (mpop(m) == 9 && is_cap(m)) {
            nconic++;
            map_put(&set, m, 0);
        }
    }
    printf("quads_forms_up_to_scalar=%lld\n", nforms);
    printf("quads_with_9point_arc_zeros=%lld\n", nconic);
    printf("quads_distinct_conics=%zu\n", set.used);
    map_free(&set);
}

/* ------------------------------------------------ orbit decomposition */
static Map g_map; /* reused for the mask -> array-index map */

static void decompose_size(int k, int verbose) {
    size_t n = CAPN[k];
    if (n == 0) { printf("decomp k=%d norbits=0 n=0\n", k); return; }
    map_init(&g_map, n);
    for (size_t i = 0; i < n; i++) map_put(&g_map, CAPS[k][i], (int32_t)i);
    uint8_t *vis = (uint8_t *)calloc(n, 1);
    int32_t *queue = (int32_t *)malloc(n * sizeof(int32_t));
    if (!vis || !queue) { fprintf(stderr, "OOM decomp\n"); exit(1); }
    printf("decomp k=%d n=%zu\n", k, n);
    long long norb = 0;
    for (size_t i = 0; i < n; i++) {
        if (vis[i]) continue;
        size_t head = 0, tail = 0;
        queue[tail++] = (int32_t)i;
        vis[i] = 1;
        long long cnt = 0;
        while (head < tail) {
            int32_t j = queue[head++];
            cnt++;
            Mask cur = CAPS[k][j];
            for (int g = 0; g < NGEN; g++) {
                Mask im = mact(PERM[g], cur);
                int32_t pos = map_get(&g_map, im);
                if (pos < 0) {
                    fprintf(stderr, "FATAL orbit left the cap set (k=%d)\n", k);
                    exit(1);
                }
                if (!vis[pos]) { vis[pos] = 1; queue[tail++] = pos; }
            }
        }
        printf("decomp k=%d orbit=%lld size=%lld rep=", k, norb, cnt);
        print_mask(CAPS[k][i]);
        printf("\n");
        norb++;
    }
    printf("decomp k=%d norbits=%lld\n", k, norb);
    map_free(&g_map);
    free(vis);
    free(queue);
    (void)verbose;
}

/* decomposition restricted to an explicit array (e.g. maximal 6-caps) */
static void decompose_array(Mask *arr, size_t n, const char *label) {
    if (!n) return;
    map_init(&g_map, n);
    for (size_t i = 0; i < n; i++) map_put(&g_map, arr[i], (int32_t)i);
    uint8_t *vis = (uint8_t *)calloc(n, 1);
    int32_t *queue = (int32_t *)malloc(n * sizeof(int32_t));
    long long norb = 0;
    for (size_t i = 0; i < n; i++) {
        if (vis[i]) continue;
        size_t head = 0, tail = 0;
        queue[tail++] = (int32_t)i;
        vis[i] = 1;
        long long cnt = 0;
        while (head < tail) {
            int32_t j = queue[head++];
            cnt++;
            for (int g = 0; g < NGEN; g++) {
                Mask im = mact(PERM[g], arr[j]);
                int32_t pos = map_get(&g_map, im);
                if (pos < 0) {
                    fprintf(stderr, "FATAL %s orbit left the set\n", label);
                    exit(1);
                }
                if (!vis[pos]) { vis[pos] = 1; queue[tail++] = pos; }
            }
        }
        printf("decomp_%s orbit=%lld size=%lld rep=", label, norb, cnt);
        print_mask(arr[i]);
        printf("\n");
        norb++;
    }
    printf("decomp_%s norbits=%lld n=%zu\n", label, norb, n);
    map_free(&g_map);
    free(vis);
    free(queue);
}

/* ------------------------------------------------------------------ main */
int main(int argc, char **argv) {
    gf_init();
    points_init();
    group_init();

    const char *board = NULL;
    for (int i = 2; i < argc; i++) board = argv[i];

    const char *cmd = argc > 1 ? argv[1] : "all";
    int do_verify = 0, do_order = 0, do_census = 0, do_decomp = 0, do_orbits = 0, do_quads = 0;
    if (!strcmp(cmd, "all")) { do_verify = do_order = do_census = do_decomp = do_orbits = do_quads = 1; }
    else if (!strcmp(cmd, "verify")) do_verify = 1;
    else if (!strcmp(cmd, "order")) do_order = 1;
    else if (!strcmp(cmd, "census")) do_census = 1;
    else if (!strcmp(cmd, "decompose")) { do_census = 1; do_decomp = 1; }
    else if (!strcmp(cmd, "orbits")) do_orbits = 1;
    else if (!strcmp(cmd, "quads")) do_quads = 1;
    else { fprintf(stderr, "unknown command %s\n", cmd); return 2; }

    if (do_verify) {
        printf("== verify ==\n");
        printf("npoints=%d nlines=%d\n", 73, 73);
        if (board && load_board(board)) {
            printf("board_file_ok=1\n");
            printf("board_lines_match_constructed=%d\n", board_matches());
            /* syntax */
            int ok = 1;
            for (int i = 0; i < 73; i++) {
                Mask s = {0, 0};
                for (int j = 0; j < 9; j++) s = mset(s, BOARD[i][j]);
                if (mpop(s) != 9) ok = 0;
            }
            printf("board_each_line_9_distinct=%d\n", ok);
        } else {
            printf("board_file_ok=0\n");
        }
        /* generators are collineations */
        for (int g = 0; g < NGEN; g++) {
            int ok = 1;
            for (int t = 0; t < 73; t++) {
                Mask im = mact(PERM[g], LINE[t]);
                int hit = 0;
                for (int u = 0; u < 73; u++) if (meq(LINE[u], im)) { hit = 1; break; }
                if (!hit) { ok = 0; break; }
            }
            /* permutation? */
            int seen[73];
            for (int i = 0; i < 73; i++) seen[i] = 0;
            for (int i = 0; i < 73; i++) seen[PERM[g][i]]++;
            int isperm = 1;
            for (int i = 0; i < 73; i++) if (seen[i] != 1) isperm = 0;
            printf("gen_%s_det=%d collineation=%d permutation=%d\n",
                   GENNAME[g], matdet(GENM[g]), ok, isperm);
        }
    }

    if (do_order) {
        printf("== order ==\n");
        int a = 0, b = 1, c = 9, d = 18; /* ordered 4-arc, checked below */
        Mask s = mask_of((int[]){a, b, c, d}, 4);
        printf("arc4_start_is_cap=%d rep=", is_cap(s));
        print_mask(s);
        printf("\n");
        long long o = order_via_4arcs(a, b, c, d);
        printf("order_generated_group=%lld\n", o);
        /* |GL(3,8)| = (8^3-1)(8^3-8)(8^3-8^2), |PGL| = |GL|/7 */
        long long gl = 511LL * 504LL * 448LL;
        printf("order_gl3_8=%lld order_pgl3_8=%lld\n", gl, gl / 7);
    }

    if (do_quads) {
        printf("== quads ==\n");
        enum_quads();
    }

    if (do_census) {
        printf("== census ==\n");
        census(do_decomp ? 1 : 0);
        long long tot = 0;
        for (int k = 1; k <= 15; k++) {
            if (CNT[k]) {
                printf("census k=%d n=%lld\n", k, CNT[k]);
                tot += CNT[k];
            }
        }
        printf("census_total=%lld\n", tot);
        printf("census_max6=%zu\n", MAX6N);
    }

    if (do_decomp) {
        printf("== decompose ==\n");
        for (int k = 1; k <= 10; k++) {
            if (CNT[k]) decompose_size(k, 1);
        }
        printf("== decompose maximal 6-caps ==\n");
        decompose_array(MAX6, MAX6N, "max6");
    }

    if (do_orbits) {
        printf("== orbits ==\n");
        Mask conic = conic_mask();
        printf("conic_n=%d conic_is_cap=%d conic=", mpop(conic), is_cap(conic));
        print_mask(conic);
        printf("\n");

        /* conic layer: number of conics = orbit of the 9-point conic */
        Orbit o;
        orbit_init(&o);
        long long nconic = orbit_run(&o, conic);
        printf("conic_orbit_k9=%lld\n", nconic);
        /* store all conics for later subset tests */
        size_t ncon = o.elems.n;
        Mask *conics = (Mask *)malloc(ncon * sizeof(Mask));
        memcpy(conics, o.elems.items, ncon * sizeof(Mask));
        orbit_free(&o);

        /* conic k-subsets, k = 5..9 */
        int cpts[9], cn = 0;
        for (int i = 0; i < 73; i++) if (mget(conic, i) && cn < 9) cpts[cn++] = i;
        printf("conic_points_n=%d\n", cn);
        long long want[10];
        want[5] = 0; /* filled below via C(9,k) * ncon */
        for (int k = 5; k <= 9; k++) {
            long long c = 1;
            for (int t = 0; t < k; t++) c = c * (9 - t) / (t + 1); /* C(9,k) */
            want[k] = (long long)ncon * c;
        }
        for (int k = 5; k <= 9; k++) {
            Orbit ob;
            orbit_init(&ob);
            Mask start = mask_of(cpts, k);
            long long osz = orbit_run(&ob, start);
            printf("conic_orbit_k%d=%lld expected=%lld rep=", k, osz, want[k]);
            print_mask(start);
            printf("\n");
            orbit_free(&ob);
        }

        /* hyperoval = conic + nucleus (1,0,0) = point 9 */
        Mask hyp = mset(conic, 9);
        printf("hyperoval_n=%d is_cap=%d\n", mpop(hyp), is_cap(hyp));
        {
            Orbit ob;
            orbit_init(&ob);
            long long osz = orbit_run(&ob, hyp);
            printf("hyperoval_orbit_k10=%lld\n", osz);
            orbit_free(&ob);
        }

        /* K1327 start caps */
        struct { const char *name; int pts[10]; int n; long long expect; } starts[] = {
            {"cap7",     {12, 16, 18, 22, 54, 66, 69}, 7, 2747136LL},
            {"cap8",     {12, 16, 18, 22, 40, 54, 66, 69}, 8, 1177344LL},
            {"cap6_nm",  {1, 10, 12, 59, 62, 65}, 6, 4120704LL},
            {"cap6_max", {10, 47, 49, 55, 61, 64}, 6, 686784LL},
        };
        for (int s = 0; s < 4; s++) {
            Mask m = mask_of(starts[s].pts, starts[s].n);
            int capok = is_cap(m);
            int maxok = is_max_cap(m);
            int conic_subset = 0;
            for (size_t t = 0; t < ncon; t++)
                if (meq(mand(m, conics[t]), m)) { conic_subset = 1; break; }
            Orbit ob;
            orbit_init(&ob);
            long long osz = orbit_run(&ob, m);
            printf("start %s n=%d is_cap=%d is_max=%d in_conic=%d size=%lld expect=%lld\n",
                   starts[s].name, starts[s].n, capok, maxok, conic_subset, osz, starts[s].expect);
            orbit_free(&ob);
        }

        /* k=9 non-conic cap: pick the first 9-cap that is not a conic */
        {
            Mask found = {0, 0};
            int got = 0;
            for (int p0 = 0; p0 < 73 && !got; p0++)
                for (int p1 = p0 + 1; p1 < 73 && !got; p1++)
                    for (int p2 = p1 + 1; p2 < 73 && !got; p2++) {
                        Mask m3 = mask_of((int[]){p0, p1, p2}, 3);
                        if (!is_cap(m3)) continue;
                        /* extend greedily */
                        Mask cur = m3;
                        for (int q = 0; q < 73; q++) {
                            if (mget(cur, q)) continue;
                            Mask t = mset(cur, q);
                            if (is_cap(t)) cur = t;
                            if (mpop(cur) == 9) break;
                        }
                        if (mpop(cur) == 9) {
                            int iscon = 0;
                            for (size_t t = 0; t < ncon; t++)
                                if (meq(conics[t], cur)) { iscon = 1; break; }
                            if (!iscon) { found = cur; got = 1; }
                        }
                    }
            if (got) {
                Orbit ob;
                orbit_init(&ob);
                long long osz = orbit_run(&ob, found);
                printf("nonconic9 size=%lld rep=", osz);
                print_mask(found);
                printf("\n");
                orbit_free(&ob);
            }
        }

        /* maximal 6-cap orbit reps: find the three orbits of maximal 6-caps and
         * probe pairwise distinctness */
        if (MAX6N == 0) census(0); /* populate MAX6 (counts only, no storage) */
        if (MAX6N) {
            decompose_array(MAX6, MAX6N, "max6b");
            /* collect reps */
            Mask reps[8];
            int nreps = 0;
            {
                Map mp;
                map_init(&mp, MAX6N);
                for (size_t i = 0; i < MAX6N; i++) map_put(&mp, MAX6[i], (int32_t)i);
                uint8_t *vis = (uint8_t *)calloc(MAX6N, 1);
                int32_t *queue = (int32_t *)malloc(MAX6N * sizeof(int32_t));
                for (size_t i = 0; i < MAX6N && nreps < 8; i++) {
                    if (vis[i]) continue;
                    reps[nreps++] = MAX6[i];
                    size_t head = 0, tail = 0;
                    queue[tail++] = (int32_t)i;
                    vis[i] = 1;
                    while (head < tail) {
                        int32_t j = queue[head++];
                        for (int g = 0; g < NGEN; g++) {
                            Mask im = mact(PERM[g], MAX6[j]);
                            int32_t pos = map_get(&mp, im);
                            if (pos >= 0 && !vis[pos]) { vis[pos] = 1; queue[tail++] = pos; }
                        }
                    }
                }
                free(vis);
                free(queue);
                map_free(&mp);
            }
            printf("max6_nreps=%d\n", nreps);
            Mask k1327 = mask_of((int[]){10, 47, 49, 55, 61, 64}, 6);
            for (int i = 0; i < nreps; i++) {
                Orbit ob;
                orbit_init(&ob);
                long long osz = orbit_run(&ob, reps[i]);
                printf("max6_rep%d size=%lld is_cap=%d is_max=%d rep=", i, osz, is_cap(reps[i]), is_max_cap(reps[i]));
                print_mask(reps[i]);
                printf("\n");
                int in = 0;
                for (size_t t = 0; t < ob.elems.n; t++)
                    if (meq(ob.elems.items[t], k1327)) { in = 1; break; }
                printf("probe k1327_max6_in_orbit%d=%d\n", i, in);
                for (int j = 0; j < nreps; j++) {
                    int inj = -1;
                    if (j != i) {
                        inj = 0;
                        for (size_t t = 0; t < ob.elems.n; t++)
                            if (meq(ob.elems.items[t], reps[j])) { inj = 1; break; }
                    }
                    printf("probe rep%d_in_orbit%d=%d\n", j, i, inj);
                }
                orbit_free(&ob);
            }
        }
        free(conics);
    }

    return 0;
}
